SourceCode.Declaration:
/// <summary>
/// Makes the selected warehouse assignment the user's default.
/// </summary>
class HSMobileOpsSetDefaultWarehouse
{

}

Method.Source:
public static void main(Args _args)
{
    HSMobileOpsUserWarehouse assignment;

    if (!_args || !_args.record() || _args.dataset() != tableNum(HSMobileOpsUserWarehouse))
    {
        throw error('Select a warehouse assignment first');
    }

    assignment = _args.record() as HSMobileOpsUserWarehouse;

    HSMobileOpsUserAdmin::makeDefaultWarehouse(assignment);
    info(strFmt('%1 is now the default warehouse', assignment.WarehouseId));
}
